*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS10200.xml';
scwin.vRowCount = 0;
scwin.processGp; //접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6, 표준코드요청 9
scwin.isCopy = true;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_list_sync
 * 설명       : 스트립통합목록을 조회한다.
 ***********************************************/
scwin.fn_list_sync = function() {
    //목록조회
    var param = '';
    var dsNm = 'BNS_STRIP_INTEG';
    var qryId = 'lds.stf.bnschg.select.listStripInteg';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};

//자동갱신
//function fn_RefreshForm(interval) {
//	setInterval("fn_list_sync();", interval);
//}

/********************************************** 
 * 함수명   : fn_SearchStrip
 * 설명       : 스트립통합 대상을 조회한다.
 ***********************************************/
scwin.fn_SearchStrip = function() {
    var param = '';
    var dsNm = 'BNS_STRIP_INTEG';
    var qryId = 'lds.stf.bnschg.select.listStripIntegTarget';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_StripInfo, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SearchStripIntegSeq
 * 설명       : 스트립통합 일련번호 조회한다.
 ***********************************************/
scwin.fn_SearchStripIntegSeq = function() {
    var param = '';
    var dsNm = 'BNS_COM_CD';
    var qryId = 'lds.stf.bnschg.select.readStripIntegTargetSeq';
    dts_Temp.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Temp, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_ProcsComplt
 * 설명       : 처리완료 및 수정을 처리한다.
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    //통합처리 리스트 갱신
    scwin.fn_list_sync();
    //스트립조회
    scwin.fn_SearchStrip();

    //sleep(3000);

    //미처리건 확인
    var param = '';
    var dsNm = 'BNS_COM_CD';
    var qryId = 'lds.stf.bnschg.select.readStripInteg';
    dts_Temp.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Temp, dsNm, qryId, param);
    if (dts_Temp.getCellData(1, 'VALUE') > 0) {
        $c.win.alert('스트립 미처리건이 존재합니다. 미처리건을 확인하여 주십시요.\n\n대상화면: 스트립신규[BNS10000], 스트립추가및재결합[BNS10100]');
        return;
    }

    //통합처리 대상건이 없을경우
    if (scwin.vRowCount == 0) {
        $c.win.alert('스트립 통합처리 대상이 존재하지 않습니다.');
        return;
    }
    scwin.processGp = '3';
    if (!confirm("처리 하시겠습니까?")) return;

    //이자만 추가한다.
    dts_Save.removeAll();

    //일련번호채번
    scwin.fn_SearchStripIntegSeq();
    for (var stripIdx = 1; stripIdx <= dts_StripInfo.getTotalRow(); stripIdx++) {
        for (var idx = 1; idx <= dts_List.getTotalRow(); idx++) {
            if (dts_List.getCellData(idx, 'STRIP_TP_CD') == '3') {
                dts_Save.insertRow();
                //스트립통합 대상
                dts_Save.setCellData(dts_Save.getRowPosition(), 'BND_APPL_ID', dts_StripInfo.getCellData(stripIdx, 'BND_APPL_ID'));
                dts_Save.setCellData(dts_Save.getRowPosition(), 'STRIP_ORGN_ISU_CD', dts_StripInfo.getCellData(stripIdx, 'STRIP_ORGN_ISU_CD'));
                dts_Save.setCellData(dts_Save.getRowPosition(), 'SEQ', dts_Temp.getCellData(1, 'VALUE'));
                //스트립통합 이자
                dts_Save.setCellData(dts_Save.getRowPosition(), 'STD_CD', dts_List.getCellData(idx, 'STD_CD'));
                dts_Save.setCellData(dts_Save.getRowPosition(), 'BF_LIST_AMT', dts_List.getCellData(idx, 'BF_LIST_AMT'));
                dts_Save.setCellData(dts_Save.getRowPosition(), 'SPRT_PAR_AMT', dts_List.getCellData(idx, 'SPRT_PAR_AMT'));
                dts_Save.setCellData(dts_Save.getRowPosition(), 'RECOMBIN_PAR_AMT', dts_List.getCellData(idx, 'RECOMBIN_PAR_AMT'));
                dts_Save.setCellData(dts_Save.getRowPosition(), 'AF_LIST_AMT', dts_List.getCellData(idx, 'AF_LIST_AMT'));
            }
        }
    }
    //alert(dts_Save.CountRow);

    var url = "/bns/Strip.do?method=processStripIntegProcessComplt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_TeamleadrConfrm
 * 설명       : 팀장확인을 처리한다.
 ***********************************************/
scwin.fn_TeamleadrConfrm = function() {
    if (scwin.vRowCount == 0) return;
    scwin.processGp = "6";
    if (dts_List.getCellData(1, 'INTEG_RSLT_CNT') == 0) {
        $c.win.alert('팀장확인은 처리완료 후 가능합니다.');
        return;
    }
    if (!window.confirm("팀장확인처리일자가 시장지파일 전송일자입니다. \n 팀장확인처리하시겠습니까?")) return;

    // 변경된 데이터가 없으면 Action이 호출되지 않음.
    // 따라서 Row를 추가함.
    dts_Temp.insertRow();
    var url = "/bns/Strip.do?method=processTeamleadrConfrm";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_Cancel
 * 설명       : 취소를 처리한다.
 ***********************************************/
scwin.fn_Cancel = function() {
    if (scwin.vRowCount == 0) return;
    scwin.processGp = "4";

    //취소가능체크
    if (dts_List.getCellData(1, 'INTEG_RSLT_CNT') == 0) {
        $c.win.alert('취소는 처리완료 후 가능합니다.');
        return;
    }

    //마감체크
    var param = '';
    var dsNm = 'BNS_COM_CD';
    var qryId = 'lds.stf.bnschg.select.readStripIntegCls';
    dts_Temp.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Temp, dsNm, qryId, param);
    if (dts_Temp.getTotalRow() > 0 &&
        dts_Temp.getCellData(1, 'VALUE') > 0) {
        $c.win.alert('채권마감 후 사용이 불가능합니다.');
        return;
    }
    if (!confirm("처리 하시겠습니까?")) return;
    dts_Temp.insertRow();
    var url = "/bns/Strip.do?method=processCancel";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_ApprovFileCreat
 * 설명       : 결재파일생성
 ***********************************************/
scwin.fn_ApprovFileCreat = function(arrPar) {
    if (dts_List.getTotalRow() == 0) return;
    var url = "/bns/BnsApprovFileDownload.do?";
    url += "BND_MKTACT_TP_CD=405";
    location.href = url;
};


// process wait state 함수 - numberMillis 수치만큼 wait.
scwin.sleep = function(numberMillis) {
    var now = new Date();
    var exitTime = now.getTime() + numberMillis;
    while (true) {
        now = new Date();
        if (now.getTime() > exitTime) return;
    }

};
scwin.gform_onload = function() {
    //숨기기
    $c.stf.showObj(grd_ExcelList, false);
    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Acpt);
    //스트립조회
    scwin.fn_SearchStrip();
    //목록 조회
    scwin.fn_list_sync();
    //1분 자동갱신
    //fn_RefreshForm(60000);
    //팀장확인데이터셋설정	

    //dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Temp.insertRow();
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    scwin.vRowCount = rowcount;
    $c.cm.CloseWin(rowcount, grd_List);
    if (rowcount > 0) {
        if (dts_List.getCellData(1, 'INTEG_RSLT_CNT') > 0) {
            btn_Proc.src = "../img/bns/btn_20_d.gif";
            btn_Proc.setDisabled(true);
        } else {
            btn_Proc.src = "../img/bns/btn_20.gif";
            btn_Proc.setDisabled(false);
        }
    }

    //헤더 복제
    if (scwin.isCopy) {
        scwin.isCopy = false;
        //저장
        $c.stf.CopyDataSetHeader(dts_List, dts_Save);
        //결재파일
        dts_ExcelList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_APPROV_FILE_WRT";
        dts_ExcelList.Reset();
    }
};
scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == '3') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "처리완료"));
    } else if (scwin.processGp == '4') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "취소"));
    } else if (scwin.processGp == '6') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "팀장확인"));
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    }
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.processGp == '3') {
        $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    } else if (scwin.processGp == '4') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "취소"));
    } else if (scwin.processGp == '6') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "팀장확인"));
    }
    scwin.fn_list_sync();
};
scwin.btn_ApprovFileCreat_onclick = function() {
    if (scwin.vRowCount == 0) return;
    scwin.fn_ApprovFileCreat();
};
scwin.btn_Proc_onclick = function() {
    scwin.fn_ProcsComplt();
};
scwin.btn_Cancel_onclick = function() {
    if (scwin.vRowCount == 0) return;
    scwin.fn_Cancel();
};
scwin.btn_TeamleadrConfrm_onclick = function() {
    if (scwin.vRowCount == 0) return;
    if (js_jobtitl == '03' && (js_duty == 'N' && js_duty_chrg == 'N')) {
        $c.win.alert('팀장권한만 가능합니다.');
        return;
    }
    scwin.fn_TeamleadrConfrm();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    var fileNm = $c.ut.cGetToday("yyyymmdd") + '_' + '스트립통합처리';
    $c.data.downloadGridViewExcel(grd_List, "스트립통합처리", "", 8);
};
scwin.btn_Search_1_onclick = function() {
    scwin.fn_list_sync();
};
